(() => {
  'use strict';
  const Store=window.FestacolSessionStore,Data=window.FestacolQuestionData,Engine=window.FestacolAssessmentEngine,root=document.getElementById('app');
  if(!Store||!Data||!Engine||!root)throw new Error('Festacol examination dependencies are unavailable.');
  const e=(v)=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
  const params=new URL(location.href).searchParams,token=params.get('session');let session=null,data=null,paper=[],candidateHash='',profile=null,state=null,timer=null,lastTick=Date.now(),review=false;
  const back=()=>`./student.html?session=${encodeURIComponent(token||'')}`;
  try{session=Store.resolveSession(Store.decodeSession(token));}catch(err){root.innerHTML=`<main class="grid min-h-dvh place-items-center p-6"><div class="alert alert-danger"><strong>Invalid exam link</strong><span>${e(err.message)}</span></div></main>`;return;}
  const effectiveStatus=()=>{const now=Date.now();if(session.status!=='open')return session.status;if(session.startsAt&&now<session.startsAt)return'scheduled';if(session.endsAt&&now>session.endsAt)return'closed';return'open';};
  const activeAuth=()=>{profile=Store.getStudentProfile();candidateHash=Store.getActiveCandidate(session.id);return Boolean(profile?.studentHash&&candidateHash&&Store.getStudentAuth()===profile.studentHash);};
  const persist=()=>{if(!state||state.submittedAt)return false;if(Store.isAttemptInvalidated(session.id,candidateHash,state.startedAt)){stopTimer();showReset();return false;}state.lastActiveAt=Date.now();return Store.saveStudentState(session.id,candidateHash,state);};
  const stopTimer=()=>{if(timer){clearInterval(timer);timer=null;}};
  const consumeElapsed=()=>{if(!state?.startedAt||state.submittedAt)return;const now=Date.now(),delta=Math.max(0,(now-lastTick)/1000);lastTick=now;state.remainingSeconds=Math.max(0,(Number(state.remainingSeconds)||0)-delta);state.elapsedActiveSeconds=(Number(state.elapsedActiveSeconds)||0)+delta;if(state.remainingSeconds<=0){state.remainingSeconds=0;persist();submit(true);}};
  const startTimer=()=>{stopTimer();lastTick=Date.now();timer=setInterval(()=>{consumeElapsed();persist();updateTimer();if(Store.isAttemptInvalidated(session.id,candidateHash,state.startedAt))showReset();},1000);};
  const formatTime=(seconds)=>{const s=Math.max(0,Math.ceil(Number(seconds)||0)),h=Math.floor(s/3600),m=Math.floor((s%3600)/60),r=s%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(r).padStart(2,'0')}`:`${m}:${String(r).padStart(2,'0')}`;};
  const updateTimer=()=>{const el=document.getElementById('exam-timer');if(el)el.textContent=formatTime(state?.remainingSeconds);const p=document.getElementById('integrity-pill');if(p)p.textContent=`Integrity ${(state?.integrityEvents||[]).filter(x=>!['focus-return','fullscreen-enter'].includes(x.type)).length}`;};
  const integrity=(type,detail='')=>{if(!state?.startedAt||state.submittedAt)return;state.integrityEvents||=[];state.integrityEvents.push({type,detail,at:Date.now()});state.integrityEvents=state.integrityEvents.slice(-100);persist();updateTimer();};
  const renderQuestion=(q,index)=>{const value=state.responses?.[String(q.id)],name=`q-${q.id}`;let control='';if(q.type==='single')control=(q.options||[]).map(opt=>`<label class="answer-option ${value===opt?'is-selected':''}"><input class="sr-only" type="radio" name="${name}" value="${e(opt)}" ${value===opt?'checked':''}><span>${e(opt)}</span></label>`).join('');else if(q.type==='multi')control=(q.options||[]).map(opt=>`<label class="answer-option ${Array.isArray(value)&&value.includes(opt)?'is-selected':''}"><input class="sr-only" type="checkbox" name="${name}" value="${e(opt)}" ${Array.isArray(value)&&value.includes(opt)?'checked':''}><span>${e(opt)}</span></label>`).join('');else if(q.type==='boolean')control=['True','False'].map(opt=>`<label class="answer-option ${String(value)===String(opt==='True')?'is-selected':''}"><input class="sr-only" type="radio" name="${name}" value="${opt==='True'?'true':'false'}" ${String(value)===String(opt==='True')?'checked':''}><span>${opt}</span></label>`).join('');else if(q.type==='fill'||q.type==='fill-multi'){const parts=Array.isArray(q.fillTemplate)?q.fillTemplate:[{text:q.prompt},{blank:true}];let bi=0;control=`<div class="flex flex-wrap items-center gap-2">${parts.map(part=>{if(!part?.blank)return`<span>${e(part?.text||'')}</span>`;const key=`b${bi++}`;return`<input class="field max-w-xs" data-fill-key="${key}" data-question-id="${q.id}" value="${e(value?.[key]||'')}" aria-label="Answer blank ${bi}">`;}).join('')}</div>`;}return`<article class="exam-card"><div class="flex flex-wrap items-center justify-between gap-3"><div><span class="badge badge-brand">${e(q.subject)}</span><span class="ml-2 text-xs font-bold text-slate-500">Question ${index+1} of ${paper.length}</span></div><button class="btn btn-ghost btn-sm" data-flag="${q.id}">${state.flagged?.includes(q.id)?'Unflag':'Flag'}</button></div>${q.passage?`<div class="surface-soft mt-5 p-4 text-sm leading-6 text-slate-700">${e(q.passage)}</div>`:''}${q.table?`<pre class="surface-soft mt-5 overflow-auto p-4 text-xs">${e(JSON.stringify(q.table,null,2))}</pre>`:''}<h2 class="mt-5 font-display text-xl font-extrabold leading-8 text-slate-950">${e(q.prompt)}</h2><div class="mt-5 grid gap-3" data-question-control="${q.id}">${control}</div></article>`;};
  const navigator=()=>`<aside class="surface p-4"><div class="flex items-center justify-between"><h3 class="font-display text-sm font-extrabold">Question navigator</h3><span id="integrity-pill" class="badge badge-warning">Integrity 0</span></div><div class="mt-4 grid grid-cols-5 gap-2">${paper.map((q,i)=>`<button class="question-chip ${i===state.currentIndex?'is-current':''} ${state.responses?.[String(q.id)]!==undefined?'is-answered':''}" data-go="${i}" aria-label="Go to question ${i+1}">${i+1}</button>`).join('')}</div><button class="btn btn-secondary mt-4 w-full" data-review>Review & submit</button></aside>`;
  const examView=()=>{const q=paper[state.currentIndex||0];root.innerHTML=`<div class="min-h-dvh bg-slate-50"><header class="glassbar sticky top-0 z-30"><div class="mx-auto flex max-w-7xl items-center gap-3 px-4 py-3 sm:px-6"><a href="${back()}" class="brand-mark" aria-label="Back to dashboard">F</a><div class="min-w-0 flex-1"><strong class="block truncate text-sm text-slate-950">${e(session.title)}</strong><span class="text-xs text-slate-500">${e(profile.fullName)} · Attempt 1 of 1</span></div><div class="rounded-xl bg-white px-3 py-2 text-right shadow-sm ring-1 ring-slate-200"><span class="block text-[10px] font-bold uppercase tracking-wider text-slate-500">Time left</span><strong id="exam-timer" class="font-display text-lg font-extrabold tabular-nums text-slate-950">${formatTime(state.remainingSeconds)}</strong></div></div></header><main class="mx-auto grid max-w-7xl gap-5 p-4 sm:p-6 lg:grid-cols-[minmax(0,1fr)_300px]">${renderQuestion(q,state.currentIndex||0)}${navigator()}</main></div>`;bindExam();updateTimer();};
  const reviewView=()=>{review=true;root.innerHTML=`<main class="mx-auto min-h-dvh max-w-5xl p-4 sm:p-8"><a class="btn btn-ghost" href="#" data-back-exam>← Back to exam</a><section class="surface-raised mt-4 p-6"><span class="badge badge-warning">Final review</span><h1 class="mt-3 font-display text-3xl font-extrabold">Review your paper</h1><p class="mt-2 text-sm text-slate-600">You have answered ${Object.keys(state.responses||{}).length} of ${paper.length} questions. Submission is final.</p><div class="mt-5 grid grid-cols-5 gap-2 sm:grid-cols-10">${paper.map((q,i)=>`<button class="question-chip ${state.responses?.[String(q.id)]!==undefined?'is-answered':''}" data-go-review="${i}">${i+1}</button>`).join('')}</div><button class="btn btn-primary btn-lg mt-6" data-submit>Submit examination</button></section></main>`;bindReview();};
  const briefing=()=>{root.innerHTML=`<main class="mx-auto grid min-h-dvh max-w-5xl place-items-center p-4 sm:p-8"><section class="surface-raised w-full overflow-hidden lg:grid lg:grid-cols-[1fr_280px]"><div class="p-6 sm:p-8"><span class="badge badge-brand">Candidate-specific paper</span><h1 class="mt-4 font-display text-3xl font-extrabold">${e(session.title)}</h1><p class="mt-3 text-sm leading-6 text-slate-600">${paper.length} questions · ${e(Store.durationLabel(session.durationSeconds))} · Attempt 1 of 1.</p><div class="alert alert-info mt-5"><strong>Resume policy</strong><span>If you leave before submission, your remaining time is saved. Returning with the same first-name username and last-name password resumes this exact attempt; it never restarts.</span></div><button class="btn btn-primary btn-lg mt-6" data-start>Start examination</button><a class="btn btn-ghost mt-2" href="${back()}">Back to dashboard</a></div><div class="illustration-well p-6"><img src="https://raw.githubusercontent.com/themesberg/flowbite-illustrations/main/src/3d/light/man-question-marks.svg" alt="Student preparing for an examination" class="mx-auto h-60"></div></section></main>`;document.querySelector('[data-start]')?.addEventListener('click',start);};
  const locked=()=>{const a=Store.findAttempt(session.id,candidateHash);root.innerHTML=`<main class="grid min-h-dvh place-items-center p-6"><section class="surface-raised max-w-xl p-7 text-center"><span class="badge badge-success">Attempt locked</span><h1 class="mt-4 font-display text-3xl font-extrabold">This examination has already been submitted.</h1><p class="mt-3 text-sm text-slate-600">Attempt 1 of 1 is complete. You cannot restart this paper.</p><p class="mt-4 text-2xl font-extrabold">${a?.score??0}%</p><a href="${back()}&page=analytics" class="btn btn-primary mt-5">View dashboard analytics</a></section></main>`;};
  const showReset=()=>{stopTimer();root.innerHTML=`<main class="grid min-h-dvh place-items-center p-6"><section class="surface-raised max-w-xl p-7 text-center"><span class="badge badge-warning">Attempt reset</span><h1 class="mt-4 font-display text-3xl font-extrabold">Your unfinished attempt was reset by an administrator.</h1><p class="mt-3 text-sm text-slate-600">Return to the student dashboard and authenticate again to start a fresh attempt.</p><a href="${back()}" class="btn btn-primary mt-5">Return to dashboard</a></section></main>`;};
  const start=async()=>{if(effectiveStatus()!=='open')return;const existing=Store.getStudentState(session.id,candidateHash);if(existing?.startedAt&&!existing.submittedAt){state=existing;paper=Engine.paperForStudent(data,session,candidateHash);startTimer();examView();return;}if(Store.hasSubmittedAttempt(session.id,candidateHash)){locked();return;}const resetAt=Store.getAttemptResetAt(session.id,candidateHash);paper=Engine.paperForStudent(data,session,candidateHash);const fingerprint=await Engine.paperFingerprint(session.id,candidateHash,paper),aHash=await Engine.attemptHash(session.id,candidateHash,fingerprint),now=Date.now();state={version:3,candidateHash,studentHash:profile.studentHash,studentName:profile.fullName,firstName:profile.firstName,lastName:profile.lastName,startedAt:Math.max(now,resetAt+1),submittedAt:null,attemptHash:aHash,paperFingerprint:fingerprint,questionIds:paper.map(q=>q.id),responses:{},flagged:[],questionTimings:{},currentIndex:0,remainingSeconds:session.durationSeconds,elapsedActiveSeconds:0,integrityEvents:[]};Store.saveStudentState(session.id,candidateHash,state);Store.recordAttempt({id:aHash.slice(0,12),attemptHash:aHash,candidateHash,studentHash:profile.studentHash,paperFingerprint:fingerprint,sessionId:session.id,sessionTitle:session.title,firstName:profile.firstName,lastName:profile.lastName,studentName:profile.fullName,classLevel:session.classLevel,classGroup:session.classGroup,academicSession:session.academicSession,mode:session.mode,subjects:session.subjects,startedAt:state.startedAt,remainingSeconds:state.remainingSeconds,questionCount:paper.length,questionIds:state.questionIds});try{if(session.integrityPolicy.fullscreenPrompt&&document.documentElement.requestFullscreen){await document.documentElement.requestFullscreen();integrity('fullscreen-enter');}}catch{integrity('fullscreen-denied');}startTimer();examView();};
  const submit=(auto=false)=>{if(state?.submittedAt)return;consumeElapsed();state.submittedAt=Date.now();stopTimer();const result=Engine.scoreAttempt(paper,state,session);Object.assign(state,{score:result.accuracy,completion:result.completion,paceIndex:result.paceIndex,reasoningIndex:result.reasoningIndex,integrityScore:result.integrityScore,subjectStats:result.subjectStats,placement:result.placement||null,details:result.details});Store.saveStudentState(session.id,candidateHash,state);Store.recordAttempt({id:state.attemptHash.slice(0,12),attemptHash:state.attemptHash,candidateHash,studentHash:profile.studentHash,paperFingerprint:state.paperFingerprint,sessionId:session.id,sessionTitle:session.title,firstName:profile.firstName,lastName:profile.lastName,studentName:profile.fullName,classLevel:session.classLevel,classGroup:session.classGroup,academicSession:session.academicSession,mode:session.mode,sessionStatus:session.status,sessionEndsAt:session.endsAt,subjects:session.subjects,startedAt:state.startedAt,submittedAt:state.submittedAt,remainingSeconds:state.remainingSeconds,elapsedActiveSeconds:state.elapsedActiveSeconds,answered:Object.keys(state.responses).length,questionCount:paper.length,score:result.accuracy,correctCount:result.correctCount,completion:result.completion,paceIndex:result.paceIndex,reasoningIndex:result.reasoningIndex,integrityScore:result.integrityScore,integrityEvents:state.integrityEvents,subjectStats:result.subjectStats,placement:result.placement||null,details:result.details,questionIds:state.questionIds});root.innerHTML=`<main class="grid min-h-dvh place-items-center p-6"><section class="surface-raised max-w-xl p-7 text-center"><span class="badge badge-success">Attempt locked</span><h1 class="mt-4 font-display text-3xl font-extrabold">${auto?'Time expired — submitted automatically':'Examination submitted'}</h1><p class="mt-3 text-sm text-slate-600">Your first and only attempt is now final.</p><strong class="mt-5 block font-display text-5xl font-extrabold">${result.accuracy}%</strong>${result.placement?`<p class="mt-4 text-sm font-bold">Recommended stream: ${e(result.placement.assignedTrack)} · ${result.placement.confidence}% confidence</p>`:''}<a href="${back()}&page=analytics" class="btn btn-primary mt-6">Open student dashboard</a></section></main>`;};
  const bindExam=()=>{root.querySelectorAll('input[type=radio]').forEach(input=>input.addEventListener('change',()=>{const q=paper[state.currentIndex];state.responses[String(q.id)]=input.value==='true'?true:input.value==='false'?false:input.value;persist();examView();}));root.querySelectorAll('input[type=checkbox]').forEach(input=>input.addEventListener('change',()=>{const q=paper[state.currentIndex],vals=[...root.querySelectorAll(`input[name="q-${q.id}"]:checked`)].map(x=>x.value);state.responses[String(q.id)]=vals;persist();examView();}));root.querySelectorAll('[data-fill-key]').forEach(input=>input.addEventListener('input',()=>{const qid=input.dataset.questionId;state.responses[qid]||={};state.responses[qid][input.dataset.fillKey]=input.value;persist();}));root.querySelectorAll('[data-go]').forEach(btn=>btn.addEventListener('click',()=>{state.currentIndex=Number(btn.dataset.go);persist();examView();}));root.querySelector('[data-flag]')?.addEventListener('click',(ev)=>{const id=Number(ev.currentTarget.dataset.flag);state.flagged||=[];state.flagged=state.flagged.includes(id)?state.flagged.filter(x=>x!==id):[...state.flagged,id];persist();examView();});root.querySelector('[data-review]')?.addEventListener('click',reviewView);};
  const bindReview=()=>{root.querySelector('[data-back-exam]')?.addEventListener('click',(ev)=>{ev.preventDefault();review=false;examView();});root.querySelectorAll('[data-go-review]').forEach(btn=>btn.addEventListener('click',()=>{state.currentIndex=Number(btn.dataset.goReview);review=false;examView();}));root.querySelector('[data-submit]')?.addEventListener('click',()=>{const dialog=document.createElement('div');dialog.className='student-dialog-layer';dialog.innerHTML=`<div class="modal-backdrop"></div><section class="modal-card" role="dialog" aria-modal="true"><div class="p-6"><span class="badge badge-warning">Final action</span><h2 class="mt-3 font-display text-2xl font-extrabold">Submit this examination?</h2><p class="mt-2 text-sm text-slate-600">You cannot restart after submission.</p><div class="mt-5 flex gap-3"><button class="btn btn-primary" data-confirm-submit>Submit permanently</button><button class="btn btn-secondary" data-cancel-submit>Keep reviewing</button></div></div></section>`;document.body.append(dialog);dialog.querySelector('[data-confirm-submit]').addEventListener('click',()=>{dialog.remove();submit(false);});dialog.querySelector('[data-cancel-submit]').addEventListener('click',()=>dialog.remove());});};
  window.addEventListener('blur',()=>integrity('window-blur'));
  document.addEventListener('visibilitychange',()=>{if(document.hidden)integrity('tab-hidden');else integrity('focus-return');});
  document.addEventListener('fullscreenchange',()=>{if(state?.startedAt&&!state.submittedAt&&!document.fullscreenElement)integrity('fullscreen-exit');});
  ['copy','cut','paste'].forEach(type=>document.addEventListener(type,(ev)=>{if(state?.startedAt&&!state.submittedAt&&session?.integrityPolicy?.clipboardGuard){ev.preventDefault();integrity(`clipboard-${type}`);}}));
  window.addEventListener('pagehide',()=>{if(state?.startedAt&&!state.submittedAt){consumeElapsed();persist();}});
  Data.load().then(async payload=>{data=payload;if(!activeAuth()){root.innerHTML=`<main class="grid min-h-dvh place-items-center p-6"><section class="surface-raised max-w-lg p-7 text-center"><h1 class="font-display text-2xl font-extrabold">Authentication required</h1><p class="mt-2 text-sm text-slate-600">Return to the student dashboard and sign in with first-name username and last-name password.</p><a href="${back()}" class="btn btn-primary mt-5">Authenticate</a></section></main>`;return;}if(effectiveStatus()!=='open'){root.innerHTML=`<main class="grid min-h-dvh place-items-center p-6"><section class="surface-raised max-w-lg p-7 text-center"><span class="badge badge-warning">${e(effectiveStatus())}</span><h1 class="mt-4 font-display text-2xl font-extrabold">This examination is not open.</h1><a href="${back()}" class="btn btn-primary mt-5">Return to dashboard</a></section></main>`;return;}if(Store.hasSubmittedAttempt(session.id,candidateHash)){locked();return;}state=Store.getStudentState(session.id,candidateHash);if(state?.startedAt&&Store.isAttemptInvalidated(session.id,candidateHash,state.startedAt)){showReset();return;}paper=Engine.paperForStudent(data,session,candidateHash);if(state?.startedAt&&!state.submittedAt){startTimer();examView();}else briefing();}).catch(err=>{root.innerHTML=`<main class="p-6"><div class="alert alert-danger"><strong>Exam unavailable</strong><span>${e(err.message)}</span></div></main>`;});
})();
